INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (10, 8, 'theory', 'Quiz: structs and enums');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 8, 0, 'What does &self mean as the first parameter of a method?', '["the method takes the whole instance away", "the method only reads the instance''s data", "the method creates a new instance", "the method is called without an object"]', 1, '&self is a reference for reading; &mut self is for changing; self takes ownership.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 8, 1, 'How do you get a field out of a struct?', '["with a dot: u.name", "with square brackets: u[\"name\"]", "with a key: u->name", "only through a method"]', 0, 'Fields are read with a dot; for tuple structs, by number: c.0.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 8, 2, 'What does the compiler do if you forget to handle one of the enum variants in a match?', '["nothing, it picks the first one by default", "skips it and returns ()", "reports an error: the patterns are not exhaustive", "generates a _ branch by itself"]', 2, 'match must cover all the variants — so adding a variant highlights every place that needs updating.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 8, 3, 'How is Option better than null?', '["a value that may be missing is visible in the type, and you cannot use it without checking", "it works faster", "it stores more data", "you can use it as an ordinary value"]', 0, 'Some(x) or None — the compiler makes you check. The "billion-dollar mistake" with null cannot be made here.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 8, 4, 'What does "abc".parse::<i32>() return?', '["a panic", "0", "None", "Err(…) — a value of type Result"]', 3, 'parse returns a Result: Ok(number) or Err(parse error). unwrap stops the program on Err.');
